// ============================================
// VALIDATE INPUT (RFC-095 DM Resolve)
// ============================================

const input = $input.first().json;
const body = input.body || input;
const startTime = Date.now();

// --- Validate required fields ---
const errors = [];

if (!body.guild_id) errors.push('guild_id requis');
if (!body.user_id) errors.push('user_id requis');
if (!body.question || typeof body.question !== 'string') errors.push('question requis (string)');

if (errors.length > 0) {
  return {
    valid: false,
    error: {
      code: 'VALIDATION_ERROR',
      message: errors.join(', '),
      http_status: 400
    },
    start_time: startTime
  };
}

// --- Return validated data ---
return {
  valid: true,
  guild_id: body.guild_id,
  user_id: body.user_id,
  question: body.question.trim(),
  start_time: startTime
};

// ============================================
// BUILD RESOLVED RESPONSE (dispatch chatbot-core)
// ============================================

const resolveDmResponse = $('Resolve DM Personae').first().json.body;
const validateData = $('Validate Input').first().json;
const tenantData = $('Resolve Tenant').first().json.body;

const personae = resolveDmResponse.personae || {};

return {
  success: true,
  status: 'resolved',
  guild_id: validateData.guild_id,
  user_id: validateData.user_id,
  question: validateData.question,
  tenant_id: tenantData.tenant_id,

  // Personae config for chatbot-core
  personae: {
    expert_id: personae.expert_id,
    specialty_id: personae.specialty_id,
    style_id: personae.style_id,
    system_prompt: personae.system_prompt,
    llm_params: personae.llm_params || {},
    rag_source_ids: personae.rag_source_ids || [],
    notebook_ids: personae.notebook_ids || [],
    skill_ids: personae.skill_ids || [],
    models: personae.models || {},
    binding_id: personae.binding_id
  },

  // Routing metadata
  routing: {
    routed_specialty_id: resolveDmResponse.routed_specialty_id,
    routing_confidence: resolveDmResponse.routing_confidence,
    routing_method: resolveDmResponse.routing_method
  },

  // Audience info
  audience: resolveDmResponse.audience,

  _trace: {
    workflow: 'DISCORD_-_DM_Resolve',
    status: 'resolved',
    latency_ms: Date.now() - validateData.start_time
  }
};

// ============================================
// BUILD NEEDS_CLARIFICATION RESPONSE
// ============================================

const resolveDmResponse = $('Resolve DM Personae').first().json.body;
const validateData = $('Validate Input').first().json;
const tenantData = $('Resolve Tenant').first().json.body;

return {
  success: true,
  status: 'needs_clarification',
  guild_id: validateData.guild_id,
  user_id: validateData.user_id,
  question: validateData.question,
  tenant_id: tenantData.tenant_id,

  // Candidates for clarification buttons
  clarification_candidates: resolveDmResponse.clarification_candidates || [],

  // Routing metadata
  routing: {
    routing_confidence: resolveDmResponse.routing_confidence,
    routing_method: resolveDmResponse.routing_method
  },

  _trace: {
    workflow: 'DISCORD_-_DM_Resolve',
    status: 'needs_clarification',
    latency_ms: Date.now() - validateData.start_time
  }
};

// ============================================
// BUILD OUT_OF_SCOPE RESPONSE
// ============================================

const resolveDmResponse = $('Resolve DM Personae').first().json.body;
const validateData = $('Validate Input').first().json;
const tenantData = $('Resolve Tenant').first().json.body;

return {
  success: true,
  status: 'out_of_scope',
  guild_id: validateData.guild_id,
  user_id: validateData.user_id,
  question: validateData.question,
  tenant_id: tenantData.tenant_id,

  // Decline reason for plugin to format message
  decline_reason: resolveDmResponse.decline_reason,

  _trace: {
    workflow: 'DISCORD_-_DM_Resolve',
    status: 'out_of_scope',
    latency_ms: Date.now() - validateData.start_time
  }
};

// ============================================
// BUILD VALIDATION ERROR RESPONSE
// ============================================

const validateData = $('Validate Input').first().json;

return {
  success: false,
  status: 'error',
  error: validateData.error,
  _trace: {
    workflow: 'DISCORD_-_DM_Resolve',
    status: 'validation_error',
    latency_ms: Date.now() - validateData.start_time
  }
};

// ============================================
// BUILD TENANT NOT FOUND ERROR
// ============================================

const validateData = $('Validate Input').first().json;
const tenantResponse = $('Resolve Tenant').first().json;

return {
  success: false,
  status: 'error',
  error: {
    code: 'TENANT_NOT_FOUND',
    message: `Aucun tenant trouvé pour guild_id=${validateData.guild_id}`,
    http_status: 404,
    details: tenantResponse.body || null
  },
  _trace: {
    workflow: 'DISCORD_-_DM_Resolve',
    status: 'tenant_not_found',
    latency_ms: Date.now() - validateData.start_time
  }
};

